function statusFor(i){return i===0&&st.submitted?'제출 완료':baseStatus[i]}
function people(){return studentNames.map((name,i)=>({name,status:statusFor(i),i}))}
function counts(){const rows=people();return {submitted:rows.filter(s=>['분석 완료','제출 완료'].includes(s.status)).length,analysis:rows.filter(s=>s.status==='분석 완료').length,active:rows.filter(s=>s.status==='응시 중').length,failed:rows.filter(s=>s.status==='준비 실패').length}}
function teacherSelectors(){return `<label><span class="sr-only">담당 학급</span><select id="class-select"><option>1학년 2반</option></select></label><label><span class="sr-only">수업 회차</span><select id="round-select"><option>3회차 · 호작도와 상징</option></select></label>`}
function metric(title,n,unit,ic,desc){return `<section class="card metric"><div class="metric-label"><span>${title}</span>${icon(ic)}</div><strong>${n}<small>${unit}</small></strong><p>${desc}</p></section>`}
function studentTable(mode='monitor'){const filtered=people().filter(s=>(st.filter==='전체'||s.status===st.filter)&&s.name.includes(st.search));return `<section class="card table-card"><div class="section-head"><h2>${mode==='class'?'담당 학급 구성원':'학생별 응시·분석 상태'}</h2>${badge('학생 10명','gray')}</div><div class="filter-row"><div class="segments" aria-label="학생 상태 필터">${['전체','응시 중','제출 완료','분석 완료','준비 실패'].map(s=>`<button data-filter="${s}" class="${st.filter===s?'active':''}" aria-pressed="${st.filter===s}">${s}</button>`).join('')}</div><label class="search">${icon('search')}<input class="input" id="student-search" aria-label="학생 이름 검색" placeholder="학생 이름 검색" value="${esc(st.search)}"></label></div><div class="table-scroll"><table><thead><tr><th>학생</th><th>${mode==='class'?'학급 연결':'응시 상태'}</th><th>분석 상태</th><th>확인할 사항</th><th>상세</th></tr></thead><tbody id="student-rows">${filtered.length?filtered.map(s=>`<tr><td><span class="student">${av(s.name,s.i%2?'mint':'')} ${s.name}</span></td><td>${mode==='class'?badge('연결 완료','green'):badge(s.status,s.status==='준비 실패'?'amber':['분석 완료','제출 완료'].includes(s.status)?'green':'')}</td><td>${s.status==='분석 완료'?'검토 가능':['제출 완료'].includes(s.status)?'분석 대기':'—'}</td><td>${s.status==='준비 실패'?'카메라 권한·환경 점검':s.status==='제출 완료'?'제출 답안·분석 대기':s.status==='분석 완료'?'리포트·피드백 검토':'진행 상태 확인'}</td><td>${button(s.status==='준비 실패'?'원인 확인':s.status==='분석 완료'?'리포트':s.status==='제출 완료'?'제출 답안':'상태 보기','student-detail','secondary sm',`data-person="${s.name}"`)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">조건에 맞는 학생이 없습니다. 검색어·필터를 바꿔보세요.</td></tr>'}</tbody></table></div><div class="table-footer"><span id="row-count">${filtered.length}명 표시 · 학급 전체 10명</span></div></section>`}
views['t-dashboard']=()=>{const n=counts();return `${head('교사 대시보드','',teacherSelectors())}<div class="metric-grid">${metric('테스트 제출',n.submitted,'/ 10명','check','미제출과 분석 대기를 구분해요.')}${metric('응시 중',n.active,'명','book','진행 중인 학생의 상태를 확인해요.')}${metric('분석 생성',n.analysis,'명','chart','교사의 검토를 기다리고 있어요.')}${metric('준비 지원 필요',n.failed,'명','camera','점검·재보정을 안내해 주세요.')}</div><div class="grid2"><section class="card"><div class="section-head"><h2>공통으로 확인할 읽기 구간</h2>${badge('당일 지문')}</div><p class="small">3문단 · 호랑이를 익살스럽게 그린 까닭</p><p class="feedback-snippet">“이는 호랑이를 익살스럽게 그림으로써 친근한 존재로 곁에 두고 싶어 했던 심리가 반영된 것입니다.”</p><p class="small">이 구간의 반복 읽기와 서술형 응답을 함께 살펴보세요.</p><div class="divider"></div><div class="label-line">${badge('맥락 파악','gray')}${badge('추론 능력','gray')}</div><div class="actions" style="margin-top:20px">${link('학급 요약·리포트 열기 '+icon('arrow'),'t-report')}</div></section><section class="card"><div class="section-head"><h2>지금 검토할 항목</h2>${link('응시 현황','t-monitor')}</div>${[['chart','상세 리포트 '+n.analysis+'건','관찰과 해석 후보를 구분해 검토','t-report'],['edit','개인 피드백 초안','수정한 게시본만 학생에게 전달','t-feedback'],['group','협력 학습 모둠','공통 읽기 패턴·응답을 확인한 추천','t-groups']].map(([i,t,d,to])=>`<div class="review-item"><span class="tag-icon">${icon(i)}</span><div class="review-copy"><h3>${t}</h3><p>${d}</p></div>${link(icon('chevron'),to,'icon-btn')}</div>`).join('')}</section></div><section class="card" style="margin-top:23px"><div class="spread"><div><h2>오늘의 수업 · 호작도와 상징</h2><p class="small" style="margin-top:8px">당일 지문과 비교 지문의 관계를 확인하고, 수업 발문을 준비하세요.</p></div>${link('테스트 구성 보기 '+icon('arrow'),'t-builder','btn soft')}</div></section>`};
views['t-builder']=()=>`${head('수업·테스트 구성','당일 지문 1개와 선택한 비교 지문으로 수업을 준비하세요.',link('응시 현황 '+icon('arrow'),'t-monitor','btn secondary'))}<section class="card">${tabs([['passage','01 지문 구성'],['questions','02 문항·루브릭'],['assign','03 미리보기·배정']],st.builderTab,'builder')}${st.builderTab==='passage'?`<div class="grid2"><div class="builder-passage">${field('테스트 제목','testTitle',st.testTitle)}${textfield('당일 지문','testText',st.testText,'answer-editor')}</div><div><h3>비교 지문 추천</h3><p class="small" style="margin:12px 0 17px">주제·문종·논증 구조가 유사한 지문을 확인하고 선택하세요.</p><div class="resource-card card" style="background:#f8fbfd">${badge('비교 지문 후보')}<h3>공공 도서관의 문턱</h3><p>시설의 양과 실제 이용 가능성을 구분하는 공통 구조를 가지고 있어요.</p><div class="source-box">2021 고1 3월 모의고사 23번<br>추천 이유: 공공 시설·접근성 · 주장–근거 전개</div><label class="check-row"><input type="checkbox" id="compare-check" ${st.compare?'checked':''}><span>비교 지문으로 함께 구성하기</span></label></div><div style="margin-top:18px">${note('15분은 수업 운영 목표입니다. 기기 준비·보정·응답 시간을 포함한 실제 소요 시간은 별도 확인해야 합니다.')}</div></div></div><div class="actions builder-actions" style="margin-top:20px">${button('문항·루브릭 검토 '+icon('arrow'),'builder-next')}<div class="source-box"><span><strong>출처</strong> · 26년 고1 3월 모의고사 (1~3) 지문</span><span><strong>사용 범위</strong> · 수업 활용</span><span>학년: 고등학교 · 문종: 발표 · 주제: 민화 속 호랑이와 까치</span></div></div>`:st.builderTab==='questions'?`<div class="grid2"><div><h3>문항 구성 · 3개</h3>${questions.map((q,i)=>`<div class="rubric"><div class="label-line">${badge('문항 '+(i+1),'gray')}${badge(q.type)}</div><h3 style="margin-top:12px">${q.text}</h3><p>평가 근거: ${q.domain}</p>${button('정답·해설 확인','question-info','secondary sm',`data-question="${i}"`)}</div>`).join('')}</div><div><h3>기본 루브릭</h3><p class="small" style="margin:12px 0">영역별 근거를 확인하며 사용해 주세요.</p>${domains.map((d,i)=>`<div class="rubric"><h3>${d}</h3><p>${['유효 구간의 진행·재독 양상을 응답과 함께 관찰','중심 주장과 부가 사례를 구분하는 응답 확인','문장·문단의 관계를 설명하는 근거 확인','생략된 전제와 가능한 결과를 연결하는 설명 확인','주장의 한계와 근거의 타당성을 검토하는 응답 확인'][i]}</p></div>`).join('')}</div></div><div class="actions" style="margin-top:20px">${button('미리보기·배정으로 '+icon('arrow'),'builder-next')}</div>`:`<div class="grid2"><div><h2>${esc(st.testTitle)}</h2><p class="small" style="margin:12px 0 24px">지문 ${st.compare?'2':'1'}개 · 선택형 1개 · 서술형 2개<br>현재 편집 내용으로 학생 화면을 미리볼 수 있어요.</p>${button('학생 화면 미리보기','test-preview','secondary')}<div class="source-box">버전: 테스트 v1<br>루브릭: 기본 검토 기준 · 지문별 영역 근거 확인</div></div><div>${field('배정 대상','assignClass',st.className+' · 전체 10명')}${field('수업 회차','assignRound',st.round)}${field('수업 예정일','assignDate','','date')}<label class="check-row"><input type="checkbox" id="assign-review"><span>지문·문항·정답·루브릭과 대상 학급을 확인했어요.</span></label>${button(st.assigned?'배정 내용 다시 확인':'테스트 배정','assign-test','full')}${st.assigned?`<p class="version-info" style="margin-top:15px">배정 완료 · ${esc(st.className)}</p>`:''}</div></div>`}</section>`;
views['t-monitor']=()=>`${head('응시 현황','준비 실패, 응시, 제출, 분석 상태를 각각 확인하세요.',teacherSelectors())}<div class="metric-grid">${metric('학급 전체',10,'명','group','이번 회차 배정 대상')}${metric('제출한 학생',counts().submitted,'명','check','분석 완료 상태 포함')}${metric('응시 중',counts().active,'명','book','학습 진행 상태')}${metric('준비 실패',counts().failed,'명','camera','권한·기기 환경 지원 필요')}</div>${studentTable()}`;
const observations=[['읽기 유창성','3문단에서 반복해서 확인한 구간이 관찰됩니다.','호랑이에 대한 인식이 바뀌는 흐름을 확인하며 읽었을 가능성이 있습니다.','문단마다 호랑이가 어떤 존재로 그려졌는지 한 줄로 정리하게 합니다.'],['핵심 내용 파악','상징 의미 선택 문항에서 적절한 선택지를 골랐습니다.','호랑이는 수호자이자 친근한 존재, 까치는 길조라는 구분을 파악했을 수 있습니다.','호랑이와 까치의 상징을 표로 나눠 정리하게 합니다.'],['맥락 파악','문항 2의 답안에 수호자와 친근함을 함께 언급했습니다.','두려움과 친근함이라는 서로 다른 인식을 연결했을 수 있습니다.','‘하지만’, ‘그런데’ 앞뒤로 인식이 어떻게 바뀌는지 질문합니다.'],['추론 능력','까닭을 설명했지만 익살스러운 표현의 근거(큰 눈, 뭉툭한 발)는 생략했습니다.','표현과 의도를 연결하는 과정에 추가 확인이 필요합니다.','“무서운 호랑이를 왜 이렇게 그렸을까?”라고 묻습니다.'],['비판적 읽기','문항 3에서 말하기 방법은 찾았지만 효과 설명이 부족합니다.','방법을 찾는 것과 효과를 판단하는 것을 구분해 확인해야 합니다.','자료 제시, 질문, 속담이 청중에게 어떤 도움을 주는지 설명하게 합니다.']];
const heatSnippet=()=>`<p>그런데 이 그림 속 호랑이, 수호자처럼 보이시나요? 그렇습니다. 어딘지 <mark class="high">의연하고 듬직한</mark> 모습은 아닙니다. 눈은 이렇게 <mark>과장되게 크고</mark>, 발도 뭉툭하지요. 이는 호랑이를 <mark class="warm">익살스럽게 그림으로써 친근한 존재로</mark> 곁에 두고 싶어 했던 심리가 반영된 것입니다.</p>`;
const pathSvg=()=>`<svg class="report-path" viewBox="0 0 500 230" preserveAspectRatio="none" aria-hidden="true"><polyline points="45,45 220,45 140,87 375,87 65,133 295,175"/>${[[45,45],[220,45],[140,87],[375,87],[65,133],[295,175]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="8"/><text x="${x}" y="${y+3}" text-anchor="middle">${i+1}</text>`).join('')}</svg>`;
function reportAnswers(){return `<div class="stack">${questions.map((q,i)=>`<div class="rubric"><div class="label-line">${badge('문항 '+(i+1))}${badge(i===2?'검토 필요':'관찰 완료',i===2?'amber':'gray')}</div><h3 style="margin-top:12px">${q.text}</h3><p>학생 응답: ${esc(st.submitted&&st.reportStudent==='김서윤'?(i===0?questions[0].choices[Number(st.answers[0])]:st.answers[i]):['호랑이는 나쁜 기운을 막아 주는 친근한 수호자로, 까치는 기쁜 소식을 전하는 길조로 그려졌다.','호랑이의 힘이 액운을 막아 준다고 믿었지만 무섭지 않게 곁에 두고 싶어서 익살스럽게 그렸다.','자료를 가리키며 설명했다.'][i])}</p><p style="margin-top:9px">${i===0?'결과: 상징의 의미 선택 · 적절한 응답':i===1?'루브릭 관찰: 개념과 구체적 조건 연결 · 근거 보완 확인':'루브릭 관찰: 판단 이유 추가 확인 필요 · 평가 보류'}</p></div>`).join('')}</div>`}
views['t-report']=()=>`${head('학생 상세 리포트','',`<label><span class="sr-only">리포트 학생 선택</span><select id="report-select">${studentNames.filter((_,i)=>i!==8&&i!==9).map(n=>`<option ${st.reportStudent===n?'selected':''}>${n}</option>`).join('')}</select></label>${button(st.reportFinal?'검토 완료':'검토 완료로 표시','report-final','secondary')}${button(icon('download')+' 리포트 이미지','report-export','',st.reportFinal?'':'disabled')}`)}<div class="report-meta"><span>${esc(st.reportStudent)} · 인하고등학교 ${st.className}</span><span>${esc(st.round)}</span>${badge(st.reportFinal?'교사 검토 완료':'교사 검토 전',st.reportFinal?'green':'amber')}</div><div class="report-layout"><section class="card"><div class="section-head"><h2>지문과 읽기 과정</h2>${badge('시선 기록','gray')}</div><div class="report-gaze-top"><div class="report-stat-row"><div><strong>독해 속도 520&nbsp;글자/분</strong>독해 속도가 평균 대비 느린 편입니다.</div><div><strong>시선 고정 시간 292ms</strong>시선 고정 시간은 평균 대비 깁니다.</div><div><strong>시폭 7.9글자</strong>시폭은 평균 대비 짧습니다.</div></div><div class="gz-obs"><div><label>오래 머문 단어</label><p>의연하고, 길조 · 한 단어에 1.5초 이상</p></div><div><label>되돌아 읽기</label><p>문장 안 2회 · 문장 사이 3회 · 문단 사이 1회 (고정 대비 14%)</p></div><div><label>주의 이탈</label><p>2초 이상 지문을 벗어난 구간은 없어요.</p></div><div><label>건너뛴 단어</label><p>첫 읽기에서 지나친 단어 28%</p></div></div></div>${tabs([['heat','히트맵'],['path','시선 경로'],['answer','응답·루브릭']],st.reportTab,'report')}${st.reportTab==='answer'?reportAnswers():`<h3>${passageTitle}</h3><p class="small" style="margin-top:10px">3문단 · 호랑이를 익살스럽게 그린 까닭</p><div class="heatmap-passage">${heatSnippet()}${st.reportTab==='path'?pathSvg():''}</div><div class="heat-legend"><span>응시 시간 짧음</span><i></i><span>김</span></div>`}</section><aside class="stack"><section class="card report-summary-card"><h3>종합 결과</h3><p class="small" style="margin-top:14px" data-summary-level>현재 문해력 수준은 노력요함입니다.</p><div class="divider"></div><p class="small" data-summary-rank>학습자는 학년 상위 73%입니다.</p></section>${reportGrowthChart()}<section class="card"><h3>이 관찰을 다음 지도로</h3><p class="small" style="margin:13px 0 18px">분석 설명을 검토하고, 학생에게 전달할 말로 다듬어 주세요.</p>${link('개인 피드백 편집 '+icon('arrow'),'t-feedback','btn soft')}<div style="margin-top:13px">${link('모둠 추천 확인','t-groups')}</div></section></aside></div><section class="card" style="margin-top:23px"><div class="section-head"><h2>5개 영역 · 관찰과 지도 제안</h2></div>${observations.map(([d,o,i,g])=>`<div class="analysis-row"><h3>${d}</h3><div class="analysis-details"><div><label>관찰</label><p>${o}</p></div><div><label>해석 후보 · 확인 필요</label><p>${i}</p></div><div><label>지도 제안</label><p>${g}</p></div></div></div>`).join('')}</section>`;
views['t-feedback']=()=>`${head('개인 피드백 편집','분석 초안을 검토·수정한 뒤 학생에게 게시하세요.',`<label><span class="sr-only">피드백 대상</span><select id="feedback-select">${studentNames.map(n=>`<option ${st.feedbackStudent===n?'selected':''}>${n}</option>`).join('')}</select></label>${button('리포트 근거 보기','feedback-evidence','secondary')}`)}<div class="grid-main"><section class="card editor-fields"><div class="section-head"><h2>${esc(st.feedbackStudent)} 학생에게 전할 피드백</h2>${badge('교사 편집 중','amber')}</div><p class="small" style="margin-bottom:22px">${passageTitle} · 3회차</p>${textfield('강점','feedbackDraft.strength',st.feedbackDraft.strength)}${textfield('보완할 개념','feedbackDraft.concept',st.feedbackDraft.concept)}${textfield('다음 읽기 전략','feedbackDraft.strategy',st.feedbackDraft.strategy)}<div class="actions">${button('분석 초안 불러오기','feedback-generate','secondary')}${button('학생에게 게시','feedback-review')}</div><div class="divider"></div><p class="version-info">현재 학생 게시본: v${st.feedbackVersion} · 초안은 게시 전 학생 화면에 반영되지 않습니다.</p></section><aside class="stack"><section class="card"><h3>검토할 근거</h3><p class="small" style="margin-top:13px">중심 주장 선택 응답, 2문단의 재독 구간, 문항 2·3의 근거 설명을 함께 살펴보세요.</p></section><section class="card"><h3>수업 방향·개인 전략</h3><p class="small" style="margin-top:13px">수업 발문: “무서운 호랑이를 왜 익살스럽게 그렸을까?”<br><br>후속 활동: 호랑이와 까치의 상징을 근거 문장과 함께 표로 정리하기</p></section>${note('게시 버튼을 누른 내용만 학생의 피드백 화면에 표시됩니다.')}</aside></div>`;
views['t-groups']=()=>`${head('모둠 편성','같은 지문의 읽기 패턴과 응답을 함께 보고 구성하세요.',link('모둠 운영 '+icon('arrow'),'t-operation','btn secondary'))}<div class="note" style="margin-bottom:23px">${icon('info')}<span>추천 → 구성 조정 → 교사 확정 순서로 모둠을 정해요. 학생 이동은 선택 메뉴로 할 수 있어요.</span></div><div class="grid2">${[0,1].map(g=>`<section class="card"><div class="section-head"><h2>${g===0?'논리 엮기 그룹':'관점 탐색 모둠'}</h2>${badge(Object.values(st.groups).filter(n=>n===g).length+'명')}</div><p class="small">${g===0?'목표: 여러 근거를 연결해 설명하기':'목표: 주장에 포함되지 않은 조건 검토하기'}</p><div class="group-reason"><strong>추천 이유</strong><br>${g===0?'같은 문단의 반복 확인 구간과 근거 연결이 생략된 응답을 함께 검토하는 후보입니다.':'주장의 조건·반론 구간을 읽는 양상과 판단 이유를 함께 확인하는 후보입니다.'}</div><div class="group-members">${Object.entries(st.groups).filter(([,id])=>id===g).map(([n])=>`<div class="member-row">${av(n,g?'mint':'')}<span>${n}</span><label style="margin-left:auto"><span class="sr-only">${n} 모둠 이동</span><select data-move="${n}"><option value="0" ${g===0?'selected':''}>근거 연결</option><option value="1" ${g===1?'selected':''}>관점 탐색</option></select></label></div>`).join('')}</div></section>`).join('')}</div><section class="card" style="margin-top:23px"><div class="section-head"><h2>개별 확인이 필요한 학생</h2>${badge('자동 편성 보류','amber')}</div><p class="small">이서준 · 준비 실패로 유효 시선 기록 없음<br>강다은 · 아직 응시하지 않아 응답·시선 근거 부족</p></section><div class="actions" style="margin-top:23px">${button(st.groupsConfirmed?'현재 편성 확인':'조정한 편성 확정','groups-confirm')}${badge(st.groupsConfirmed?'편성 확정 상태':'구성 변경 · 확정 필요',st.groupsConfirmed?'green':'amber')}</div>`;
views['t-operation']=()=>`${head('모둠 운영','목표·과제를 배정하고 토론과 공동 결과물을 확인하세요.',link('구성 조정','t-groups','btn secondary'))}<div class="grid2"><section class="card"><div class="section-head"><h2>${groupName()}</h2>${badge(st.groupAssigned?'과제 배정됨':'배정 전',st.groupAssigned?'green':'gray')}</div>${memberAvatars()}<div class="divider"></div>${field('활동 목표','groupGoalDraft',st.groupGoalDraft)}${textfield('협력 과제','groupTaskDraft',st.groupTaskDraft)}<div class="source-box">자료: ${passageTitle}<br>공동 지문·근거 표시·주석·토론·공동 결과물</div>${button('목표·과제 배정','group-assign')}</section><section class="card"><div class="section-head"><h2>활동 현황</h2>${badge(st.groupSubmitted?'제출 완료':'활동 중',st.groupSubmitted?'green':'')}</div><div class="report-stat-row"><div><strong>${2+st.comments.length}</strong>의견</div><div><strong>${st.comments.filter(c=>c.quote!==null).length+2}</strong>근거 연결</div><div><strong>${st.groupSubmitted?'제출':'작성 중'}</strong>결과물</div></div><div class="divider"></div><h3>최근 주석·토론</h3>${st.comments.length?st.comments.map(c=>`<div class="quote"><strong>${esc(c.name)}</strong><br>${esc(c.text)}${c.quote!==null?'<br>근거: '+esc(sentences[c.quote]):''}</div>`).join(''):'<p class="small" style="margin-top:15px">이지우 · 호랑이가 수호자로 받아들여진 까닭을 짚은 의견<br>박하린 · 익살스러운 표현의 의도를 연결한 의견</p>'}<div class="divider"></div><h3>공동 결과물</h3><p class="feedback-snippet">${st.summary?esc(st.summary):'아직 작성한 결과물이 없습니다. 학생이 우리 모둠 화면에서 작성하면 이곳에 반영돼요.'}</p>${textfield('모둠에 전할 교사 피드백','groupFeedbackDraft',st.groupFeedbackDraft)}${button('모둠 피드백 게시','group-feedback','secondary')}</section></div>`;
const resources=[{title:passageTitle,type:'passages',tag:'발표 · 민화와 상징',desc:'호랑이와 까치에 담긴 옛사람들의 생각과 발표의 말하기 방법을 함께 살피는 읽기 자료.'},{title:'공공 도서관의 문턱',type:'passages',tag:'설명·논증 · 비교 지문',desc:'시설의 수와 이용 가능성을 연결하는 비교 자료.'},{title:'숫자는 무엇을 설명하는가',type:'passages',tag:'논설문 · 비판적 읽기',desc:'지표의 의미와 설명의 한계를 검토하는 추가 학습 자료.'},{title:'중심 주장 선택 문항',type:'questions',tag:'선택형 · 핵심 내용 파악',desc:'정답과 해설, 평가 영역을 연결한 문항.'},{title:'근거를 연결하는 서술형 문항',type:'questions',tag:'서술형 · 맥락·추론',desc:'문장 사이의 관계와 근거 설명을 확인하는 문항.'},{title:'기본 관찰·평가 루브릭',type:'rubrics',tag:'기본 루브릭 · 5개 영역',desc:'관찰과 해석 후보, 지도 제안을 구분하는 기준.'},{title:'내 루브릭 · 근거 연결 읽기',type:'rubrics',tag:'교사 작성',desc:'근거 선택과 설명의 연결을 확인하는 수업용 기준.'},{title:'공간을 평가하는 기준 토론',type:'tasks',tag:'협력 과제 · 관점 비교',desc:'주장에 빠진 조건을 찾아 근거와 함께 설명하기.'}];
views['t-library']=()=>{const list=[...resources,...st.extraResources].filter(r=>r.type===st.resourceTab&&r.title.includes(st.resourceSearch));return `${head('자료실','출처와 사용 범위를 확인하고 수업 자료를 구성하세요.',button('자료 등록','resource-add'))}<section class="card" style="margin-bottom:23px">${tabs([['passages','지문'],['questions','문항·정답·해설'],['rubrics','기본·내 루브릭'],['tasks','협력 과제·전략']],st.resourceTab,'library')}<label class="search">${icon('search')}<input id="resource-search" class="input" aria-label="자료 검색" placeholder="자료 제목 검색" value="${esc(st.resourceSearch)}"></label></section><div class="grid3" id="resource-list">${list.map(r=>`<article class="card resource-card">${badge(r.tag)}<h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p><span class="source">${esc(r.source??'출처: LOOKteracy 자체 제작')}<br>${esc(r.scope??'사용 범위: 수업 활용')}</span><div class="actions">${button('미리보기','resource-view','secondary sm',`data-resource-title="${esc(r.title)}"`)}${button('수업에 선택','resource-use','soft sm',`data-resource-title="${esc(r.title)}"`)}</div></article>`).join('')||'<div class="card empty">검색 조건에 맞는 자료가 없습니다.</div>'}</div>`};
views['t-class']=()=>`${head('학급·학생 관리','담당 학급의 구성과 연결·참여 상태를 확인하세요.',button('학급 연결 안내','class-connect','secondary'))}<section class="card" style="margin-bottom:23px"><div class="spread"><div><span class="eyebrow">MY CLASS</span><h2 style="margin:10px 0">인하고등학교 · 1학년 2반</h2><p class="small">담당 교사: 김하늘 · 구성원 10명 · 모두 학급 연결 완료</p></div>${badge('담당 학급','green')}</div></section>${studentTable('class')}`;
